import { describe, expect, it } from "vitest";
import { createApp, type App } from "../src/app.ts";

const fixedClock = () => new Date("2026-10-01T08:00:00Z");
const makeApp = (): App => createApp({ clock: fixedClock });

function addCoupon(app: App, overrides: Record<string, unknown> = {}): void {
  const res = app.request("POST", "/coupons", {
    code: "SAVE20",
    type: "PERCENT",
    value: 20,
    validFrom: "2026-01-01T00:00:00Z",
    validUntil: "2027-01-01T00:00:00Z",
    ...overrides,
  });
  expect(res.status).toBe(201);
}

function addOrder(app: App, amountCents = 12000, customer = "alice") {
  const res = app.request("POST", "/orders", { customer, amountCents });
  expect(res.status).toBe(201);
  return res.body as { id: number };
}

describe("apply coupon - discount math", () => {
  it("applies a fixed amount coupon", () => {
    const app = makeApp();
    addCoupon(app, { type: "FIXED", value: 500 });
    const order = addOrder(app);
    const res = app.request("POST", `/orders/${order.id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({
      id: order.id,
      amountCents: 12000,
      discountCents: 500,
      finalAmountCents: 11500,
      couponCode: "SAVE20",
      status: "PENDING",
    });
  });

  it("applies a percentage coupon", () => {
    const app = makeApp();
    addCoupon(app);
    const order = addOrder(app);
    const res = app.request("POST", `/orders/${order.id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.body).toMatchObject({ discountCents: 2400, finalAmountCents: 9600, couponCode: "SAVE20" });
  });

  it("rounds a percentage discount down to whole cents", () => {
    const app = makeApp();
    addCoupon(app, { value: 10 });
    const order = addOrder(app, 999);
    const res = app.request("POST", `/orders/${order.id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.body).toMatchObject({ discountCents: 99, finalAmountCents: 900 });
  });

  it("caps the discount at maxDiscountCents", () => {
    const app = makeApp();
    addCoupon(app, { value: 100, maxDiscountCents: 300 });
    const order = addOrder(app, 1000);
    const res = app.request("POST", `/orders/${order.id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.body).toMatchObject({ discountCents: 300, finalAmountCents: 700 });
  });

  it("never discounts more than the order amount", () => {
    const app = makeApp();
    addCoupon(app, { type: "FIXED", value: 5000 });
    const order = addOrder(app, 1000);
    const res = app.request("POST", `/orders/${order.id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.body).toMatchObject({ discountCents: 1000, finalAmountCents: 0 });
  });
});

describe("apply coupon - eligibility", () => {
  it("rejects an unknown order", () => {
    const app = makeApp();
    addCoupon(app);
    const res = app.request("POST", "/orders/99/apply-coupon", { couponCode: "SAVE20" });
    expect(res.status).toBe(404);
    expect((res.body as any).error.code).toBe("ORDER_NOT_FOUND");
  });

  it("rejects an order that is not pending", () => {
    const app = makeApp();
    addCoupon(app);
    const order = addOrder(app);
    app.request("POST", `/orders/${order.id}/pay`);
    const res = app.request("POST", `/orders/${order.id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("ORDER_NOT_PENDING");
  });

  it("rejects a second coupon on the same order", () => {
    const app = makeApp();
    addCoupon(app);
    const order = addOrder(app);
    app.request("POST", `/orders/${order.id}/apply-coupon`, { couponCode: "SAVE20" });
    const res = app.request("POST", `/orders/${order.id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("ORDER_ALREADY_HAS_COUPON");
    expect((app.request("GET", `/orders/${order.id}`).body as any).discountCents).toBe(2400);
  });

  it("rejects an unknown coupon", () => {
    const app = makeApp();
    const order = addOrder(app);
    const res = app.request("POST", `/orders/${order.id}/apply-coupon`, { couponCode: "NOPE" });
    expect(res.status).toBe(404);
    expect((res.body as any).error.code).toBe("COUPON_NOT_FOUND");
  });

  it("rejects a disabled coupon", () => {
    const app = makeApp();
    addCoupon(app, { status: "DISABLED" });
    const order = addOrder(app);
    const res = app.request("POST", `/orders/${order.id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("COUPON_INACTIVE");
  });

  it("rejects a coupon that is not yet valid", () => {
    const app = makeApp();
    addCoupon(app, { validFrom: "2027-01-01T00:00:00Z", validUntil: "2028-01-01T00:00:00Z" });
    const order = addOrder(app);
    const res = app.request("POST", `/orders/${order.id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("COUPON_NOT_YET_VALID");
  });

  it("rejects an expired coupon", () => {
    const app = makeApp();
    addCoupon(app, { validFrom: "2025-01-01T00:00:00Z", validUntil: "2026-01-01T00:00:00Z" });
    const order = addOrder(app);
    const res = app.request("POST", `/orders/${order.id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("COUPON_EXPIRED");
  });

  it("rejects an order below the coupon minimum", () => {
    const app = makeApp();
    addCoupon(app, { minAmountCents: 20000 });
    const order = addOrder(app, 12000);
    const res = app.request("POST", `/orders/${order.id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("ORDER_BELOW_MIN_AMOUNT");
  });

  it("rejects a coupon that reached its usage limit", () => {
    const app = makeApp();
    addCoupon(app, { usageLimit: 1 });
    const first = addOrder(app);
    app.request("POST", `/orders/${first.id}/apply-coupon`, { couponCode: "SAVE20" });
    const second = addOrder(app, 5000, "bob");
    const res = app.request("POST", `/orders/${second.id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("COUPON_USAGE_LIMIT_REACHED");
  });

  it("rejects a missing or invalid coupon code", () => {
    const app = makeApp();
    const order = addOrder(app);
    expect(app.request("POST", `/orders/${order.id}/apply-coupon`, {}).status).toBe(400);
    const res = app.request("POST", `/orders/${order.id}/apply-coupon`, { couponCode: 5 });
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("INVALID_REQUEST");
  });
});

describe("apply coupon - redemption", () => {
  it("increments usedCount and records a redemption", () => {
    const app = makeApp();
    addCoupon(app);
    const order = addOrder(app);
    app.request("POST", `/orders/${order.id}/apply-coupon`, { couponCode: "SAVE20" });

    expect(app.request("GET", "/coupons/SAVE20").body).toMatchObject({ usedCount: 1 });
    const row = app.db
      .prepare("SELECT order_id, coupon_code, discount_cents FROM coupon_redemptions WHERE order_id = ?")
      .get(order.id) as any;
    expect(row).toMatchObject({ order_id: order.id, coupon_code: "SAVE20", discount_cents: 2400 });
  });
});

